                    return  # Temporal window expired
            else:
                return  # Barrier not open
        else:
            return  # A not triggered yet

    elif next_sw == 'C':
        # Check if B is triggered and cooldown is over
        if not b_triggered or sandbox.get_cooldown_remaining() > 0:
            return

        # Check temporal window for B→C (400 steps)
        if (step_count - sandbox.get_trigger_time('B')) > 400:
            return

        # Check altitude requirement (max y in history >= 2.9m)
        y_history = []
        MAX_Y_HISTORY = 150
        MAX_Y_FOR_C = 2.9

        # Maintain y history
        current_y = pos[1]
        y_history.append(current_y)
        if len(y_history) > MAX_Y_HISTORY:
            y_history.pop(0)
        max_y = max(y_history)

        if max_y < MAX_Y_FOR_C:
            # Navigate to platform to meet altitude requirement
            target_platform = (5.5, 3.25)
            if not is_in_platform(pos):
                apply_towards_target(target_platform)
            else:
                # Adjust speed if needed
                if speed > 0.5:
                    adjust_speed()
        else:
            # Navigate to C's zone
            target_C = (8.0, 2.0)
            if not is_in_zone_C(pos):
                apply_towards_target(target_C)
            else:
                # Adjust speed if needed
                if speed > 0.5:
                    adjust_speed()
        # Check if in zone long enough
        steps_in_zone = sandbox.get_steps_in_current_zone()
        if steps_in_zone >= 25:
            c_triggered = True

    # Continuous speed adjustment
    adjust_speed()
